import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

depthwise_conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size, int channels,
    int in_h, int in_w,
    int out_h, int out_w,
    int kernel_h,
    int stride, int padding, int dilation,
    bool has_bias)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    long total = (long)batch_size * channels * out_h * out_w;
    if (idx >= total) return;

    int ow = idx % out_w;
    int oh = (idx / out_w) % out_h;
    int c = (idx / (out_w * out_h)) % channels;
    int n = idx / (out_w * out_h * channels);

    int in_w_idx = ow * stride - padding;
    float sum = 0.0f;

    if (in_w_idx >= 0 && in_w_idx < in_w) {
        int base_input_offset = (n * channels + c) * in_h;
        int weight_offset = c * kernel_h;
        #pragma unroll
        for (int kh = 0; kh < kernel_h; ++kh) {
            int in_h_idx = oh * stride - padding + kh * dilation;
            if (in_h_idx >= 0 && in_h_idx < in_h) {
                float in_val = input[(base_input_offset + in_h_idx) * in_w + in_w_idx];
                float w_val = weight[weight_offset + kh];
                sum += in_val * w_val;
            }
        }
    }

    if (has_bias) {
        sum += bias[c];
    }

    output[idx] = sum;
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();

    int batch_size = input.size(0);
    int channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);

    int kernel_h = weight.size(2); // weight shape: (channels, 1, kernel_h, 1)

    int out_h = (in_h + 2 * padding - dilation * (kernel_h - 1) - 1) / stride + 1;
    int out_w = (in_w + 2 * padding - 1) / stride + 1;

    auto output = torch::empty({batch_size, channels, out_h, out_w}, input.options());

    long total = (long)batch_size * channels * out_h * out_w;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    const float* bias_ptr = nullptr;
    if (has_bias) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }

    depthwise_conv2d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, channels,
        in_h, in_w,
        out_h, out_w,
        kernel_h,
        stride, padding, dilation,
        has_bias
    );

    return output;
}
"""

depthwise_conv2d_cpp_source = r"""
torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    bool has_bias);
"""

depthwise_conv2d = load_inline(
    name="depthwise_conv2d",
    cpp_sources=depthwise_conv2d_cpp_source,
    cuda_sources=depthwise_conv2d_source,
    functions=["depthwise_conv2d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a depthwise 2D convolution with a square input and an asymmetric kernel,
    using a custom CUDA kernel fused for the (kernel_size, 1) depthwise convolution.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.has_bias = bias

        # weight shape: (in_channels, 1, kernel_size, 1) matching nn.Conv2d depthwise groups=in_channels
        self.weight = nn.Parameter(torch.empty(in_channels, 1, kernel_size, 1))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(in_channels))
            fan_in = kernel_size
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

        self.depthwise_conv2d = depthwise_conv2d

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().cuda()
        weight = self.weight.contiguous().cuda()
        if self.has_bias:
            bias = self.bias.contiguous().cuda()
        else:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)

        return self.depthwise_conv2d.depthwise_conv2d_cuda(
            x, weight, bias,
            self.stride, self.padding, self.dilation, self.has_bias
        )

